enum Direction { Up, Down, Left, Right }

fn name(d: Direction) -> &'static str {
    match d {
        Direction::Up => "up",
        Direction::Down => "down",
        Direction::Left => "left",
    }
}

fn main() {
    println!("{}", name(Direction::Up));
}

fn classify(n: i32) -> &'static str {
    match n {
        i32::MIN..=-1 => "negative",
        0 => "zero",
        x if x % 2 == 0 => "even",
        _ => "odd",
    }
}

fn main() {
    println!("{} {} {}", classify(-3), classify(4), classify(7));
}

fn main() {
