trait Greet {
    fn name(&self) -> String;
    fn hello(&self) -> String {
        format!("Hello, {}", self.name())
    }
}

struct En;
struct Vi;

impl Greet for En {
    fn name(&self) -> String { "Ann".to_string() }
}

impl Greet for Vi {
    fn name(&self) -> String { "An".to_string() }
    fn hello(&self) -> String { format!("Xin chào, {}", self.name()) }
}

fn main() {
    println!("{} | {}", En.hello(), Vi.hello());
}

use std::fmt::Display;

fn make(flag: bool) -> impl Display {
    if flag { 42 } else { "none" }
}

fn main() {
    println!("{}", make(true));
}

fn largest<T>(items: &[T]) -> &T {
    let mut max = &items[0];
    for item in items {
        if item > max {
            max = item;
        }
    }
    max
}

fn main() {
    println!("{}", largest(&[3, 9, 4]));
}

trait Shape {
    fn area(&self) -> f64;
}

struct Square(f64);
struct Rect(f64, f64);

impl Shape for Square {
    fn area(&self) -> f64 { self.0 * self.0 }
}

impl Shape for Rect {
    fn area(&self) -> f64 { self.0 * self.1 }
}

fn main() {
    let shapes: Vec<Box<dyn Shape>> = vec![Box::new(Square(2.0)), Box::new(Rect(2.0, 3.0))];
    let total: f64 = shapes.iter().map(|s| s.area()).sum();
    println!("{}", total);
}

