use std::num::ParseIntError;

#[derive(Debug)]
enum AppError {
    Parse(String),
}

impl From<ParseIntError> for AppError {
    fn from(e: ParseIntError) -> Self {
        AppError::Parse(e.to_string())
    }
}

fn double(s: &str) -> Result<i32, AppError> {
    let n: i32 = s.parse()?;
    Ok(n * 2)
}

fn main() {
    println!("{:?}", double("21"));
    println!("{:?}", double("x"));
}

fn parse_pos(s: &str) -> Result<u32, String> {
    s.trim().parse::<u32>().map_err(|_| format!("bad: {}", s))
}

fn main() {
    let r1 = parse_pos(" 7 ").map(|n| n * 10);
    let r2 = parse_pos("-1").and_then(|n| Ok::<u32, String>(n + 1));
    println!("{:?} {:?}", r1, r2);
}

use std::collections::HashMap;

fn main() {
    let text = "a b a c a b";
    let mut counts = HashMap::new();
    for w in text.split_whitespace() {
        *counts.entry(w).or_insert(0) += 1;
    }
    println!("{} {} {}", counts["a"], counts["b"], counts["c"]);
}

