fn make_adder(n: i32) -> impl Fn(i32) -> i32 {
    move |x| x + n
}

fn main() {
    let add5 = make_adder(5);
    let mut counter = 0;
    let mut tick = || counter += 1;
    tick();
    tick();
    println!("{} {}", add5(10), counter);
}

