use std::sync::mpsc;
use std::thread;

fn main() {
    let (tx, rx) = mpsc::channel();
    thread::spawn(move || {
        for i in 1..=3 {
            tx.send(i * 10).unwrap();
        }
    });
    let total: i32 = rx.iter().sum();
    println!("{}", total);
}

use std::rc::Rc;
