fn main() {
    let shared = Rc::new(5);
    let s2 = Rc::clone(&shared);
    let h = thread::spawn(move || {
        println!("{}", s2);
    });
    h.join().unwrap();
}

use std::rc::Rc;

async fn tick() {}

async fn work() {
    let data = Rc::new(1);
    tick().await;
    println!("{}", data);
}

fn require_send<T: Send>(_: T) {}

fn main() {
    require_send(work());
}
